<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import PageHeader from '../../components/common/PageHeader.vue'
import AppSelect from '../../components/common/AppSelect.vue'
import { mealsApi,monday,shiftDay,emptyMenu,emptyOption,copyWeek,mealNames,textures,tokenList,type WeeklyMenu,type Meal,type Texture,type Requirement,type Profile,type Coverage,type Kitchen,type GeneratedMenu,type ProfileReading } from '../../api/meals'
const tab=ref('needs'),week=ref(monday()),menu=ref<WeeklyMenu>(emptyMenu(week.value)),day=ref(0),busy=ref(false),error=ref(''),notice=ref(''),baseline=ref(''),report=ref<Coverage|null>(null),ack=ref(false),requirements=ref<Requirement[]>([]),filter=ref(''),selected=ref(''),kitchen=ref<Kitchen|null>(null),kitchenDay=ref(0),kitchenMeal=ref<Meal>('lunch')
const recipeSource=ref<{enabled:boolean;configured:boolean}|null>(null)
const reading=ref<ProfileReading|null>(null)
const readingBusy=ref(false)
const generating=ref(false),generationInfo=ref<GeneratedMenu|null>(null)
const generationConfig=reactive({options_per_meal:2,available_ingredients:[] as string[],kitchen_notes:'',budget_notes:'',season:'',capacity_per_option:null as number|null,avoid_previous:true,acknowledge_pending:false})
const dirty=computed(()=>menu.value.status==='draft'&&JSON.stringify(menu.value)!==baseline.value)
onBeforeRouteLeave(()=>generating.value?window.confirm('正在生成菜单，离开后结果可能无法保留，确定离开？'):!dirty.value||window.confirm('菜单修改尚未保存，确定离开？'))
const plannedCount=computed(()=>menu.value.slots.filter(s=>s.options.length>0).length)
const optionCount=computed(()=>menu.value.slots.reduce((sum,s)=>sum+s.options.length,0))
function dayCount(n:number){return menu.value.slots.filter(s=>s.day===n&&s.options.length>0).length}
const slots=computed(()=>menu.value.slots.filter(s=>s.day===day.value))
const requirementRows=computed(()=>requirements.value.filter(r=>!filter.value||`${r.name} ${r.record_no} ${r.location}`.includes(filter.value)))
const active=computed(()=>requirements.value.find(r=>r.id===selected.value))
const profile=reactive<Profile>({version:0,resident_version:1,allergy_status:'unknown',confirmed:false,allergens:[],avoid_ingredients:[],required_tags:[],allowed_textures:[],source:'',notes:''})
function selectResident(){reading.value=null;const r=active.value;if(!r)return;Object.assign(profile,r.profile?JSON.parse(JSON.stringify(r.profile)):{version:0,resident_version:r.resident_version,allergy_status:'unknown',confirmed:false,allergens:[],avoid_ingredients:[],required_tags:[],allowed_textures:[],source:'',notes:''});profile.resident_version=r.resident_version}
function tokens(event:Event){return tokenList((event.target as HTMLInputElement).value)}
function apply(row:WeeklyMenu){menu.value=row;baseline.value=JSON.stringify(row);report.value=null;ack.value=false;kitchen.value=null}
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await work()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(){if(dirty.value&&!window.confirm('重新读取会放弃未保存菜单，是否继续？'))return;await run(async()=>{const value=monday(week.value);week.value=value;generationInfo.value=null;apply((await mealsApi.menu(value)).menu||emptyMenu(value));requirements.value=(await mealsApi.requirements()).items;recipeSource.value=await mealsApi.recipeSource()})}
async function save(){await run(async()=>{apply(await mealsApi.save(menu.value));notice.value='菜单计划已保存。'})}
async function check(){await run(async()=>{report.value=await mealsApi.coverage(menu.value.id!)})}
async function publish(){if(!window.confirm('确认已核对食材、过敏原及餐食安排？发布后本周菜单不可编辑。'))return;await run(async()=>{menu.value=await mealsApi.publish(menu.value.id!,menu.value.version,ack.value);baseline.value=JSON.stringify(menu.value);notice.value='菜单已发布，老人端可查看。'})}
async function copyPrevious(){await run(async()=>{const old=(await mealsApi.menu(shiftDay(menu.value.week_start,-7))).menu;if(!old)throw new Error('上一周没有菜单可复制');if(!window.confirm('用上一周菜单替换当前未保存的菜单计划？请随后调整本周菜品。'))return;generationInfo.value=null;const copied=copyWeek(old,menu.value.week_start);copied.id=menu.value.id;copied.version=menu.value.version;menu.value=copied;notice.value='已复制为本周计划，请调整菜品并核对。'})}
async function generateMenu(){
 if(dirty.value&&!window.confirm('生成成功后将替换当前未保存的菜单计划，是否继续？'))return
 await run(async()=>{
  generating.value=true
  try{
   const result=await mealsApi.generate({...generationConfig,week_start:menu.value.week_start,version:menu.value.version,available_ingredients:[...generationConfig.available_ingredients],capacity_per_option:generationConfig.capacity_per_option?Number(generationConfig.capacity_per_option):null})
   menu.value={...result.menu,id:result.menu.id||undefined};generationInfo.value=result;report.value=result.coverage;ack.value=false;kitchen.value=null
   notice.value='AI周菜单计划已生成，尚未保存或发布。请逐餐核对、保存，再检查全院覆盖并发布。'
  }finally{generating.value=false}
 })
}
async function readProfile(){
 const resident=active.value;if(!resident)return
 if(!window.confirm('AI读取将替换当前饮食核对表单，请先确认无需保留未保存的内容。已有登记不会被自动修改，是否继续？'))return
 await run(async()=>{readingBusy.value=true;reading.value=null;try{
  const result=await mealsApi.readProfile(resident.id)
  if(selected.value!==resident.id)return
  if(result.resident_version!==resident.resident_version)throw new Error('档案版本已变化，请重新读取页面后核对')
  Object.assign(profile,result.suggestion,{resident_version:resident.resident_version,confirmed:false})
  reading.value=result;notice.value='已根据档案预填，请逐项核对原文并补全未知信息，再确认保存。'
 }finally{readingBusy.value=false}})
}
async function saveProfile(){if(!active.value)return;await run(async()=>{await mealsApi.profile(active.value!.id,{...profile});requirements.value=(await mealsApi.requirements()).items;report.value=null;selectResident();notice.value='饮食要求已保存。已存在的选餐如需复核，会在厨房汇总标出。'})}
async function loadKitchen(){await run(async()=>{kitchen.value=await mealsApi.kitchen(menu.value.id!,shiftDay(menu.value.week_start,kitchenDay.value),kitchenMeal.value)})}
onMounted(()=>{baseline.value=JSON.stringify(menu.value);void load()})
</script>
<template><div class="page meals"><PageHeader title="每周餐食管理" subtitle="根据已核对的老人饮食要求安排一周三餐，发布后供老人选择。"/>
 <nav class="meal-tabs" aria-label="餐食管理"><button v-for="[key,label] in [['needs','饮食需求'],['menu','周菜单'],['kitchen','厨房汇总']]" :key="key" class="btn" :class="{primary:tab===key}" :aria-pressed="tab===key" @click="tab=key">{{ label }}</button></nav>
 <p v-if="error" class="meal-error" role="alert">{{ error }}</p><p v-if="notice" class="meal-notice" role="status">{{ notice }}</p>
 <div v-if="tab!=='needs'" class="card meal-toolbar"><label for="meal-week">选择周次（自动定位周一）<input id="meal-week" v-model="week" class="input" type="date" :disabled="busy"></label><button class="btn" :disabled="busy||!week" @click="load">读取这一周</button><span>{{ menu.week_start }} 至 {{ shiftDay(menu.week_start,6) }} · {{ menu.status==='draft'?'待发布':'已发布' }}</span></div>
 <template v-if="tab==='menu'">
 <div class="meal-overview"><div><span class="meal-eyebrow">WEEKLY MEAL PLANNER</span><h2>一周好食，安心安排</h2><p>先编排菜单，再核对饮食需求，审核后发布给老人。</p></div><div class="meal-metrics"><div><strong>{{ plannedCount }}<small>/ 21</small></strong><span>已安排餐次</span></div><div><strong>{{ optionCount }}</strong><span>可选餐食方案</span></div><div><strong>{{ requirements.filter(r=>!r.reviewed).length }}</strong><span>饮食资料待核实</span></div></div></div>
 <details class="card meal-section meal-ai-panel"><summary class="meal-ai-summary"><span class="meal-ai-mark"><AppIcon name="sparkles" :size="24"/></span><span><b>智能编排助手</b><small>结合全院饮食需求生成七天三餐 · 展开设置</small></span><span class="meal-expand-label">配置与生成</span></summary><div class="meal-ai-content"><div aria-labelledby="menu-ai-heading"><div class="meal-section-head"><div><h2 id="menu-ai-heading"><AppIcon name="sparkles" :size="22"/> 智能生成本周菜单</h2><p class="meal-hint">根据全院已核实的饮食条件、上周菜品和厨房约束生成七天三餐。生成后可逐餐修改，需您核实后发布。</p></div><span class="badge blue">人工审核后发布</span></div>
 <p v-if="recipeSource" class="meal-hint">外部食谱 · HowToCook：{{ !recipeSource.enabled?'未启用，当前使用模型编排':recipeSource.configured?'已配置，生成前将查询候选菜谱':'已启用，需先填写远程连接地址' }}。候选食谱仍需结合老人饮食条件与厨房能力核对。</p><fieldset :disabled="busy||menu.status!=='draft'" class="meal-fieldset meal-grid"><label for="ai-options">每餐可选方案数<AppSelect id="ai-options" v-model.number="generationConfig.options_per_meal" class="select" :disabled="busy||menu.status!=='draft'"><option v-for="count in [2,3,4]" :key="count" :value="count">{{ count }} 套完整餐食</option></AppSelect></label><label for="ai-season">季节 / 时令偏好<input id="ai-season" v-model="generationConfig.season" class="input" maxlength="30" placeholder="选填，例如：秋冬季"></label><label for="ai-ingredients">可采购食材（包括配料，逗号分隔）<textarea id="ai-ingredients" :value="generationConfig.available_ingredients.join('，')" class="input" rows="3" placeholder="选填；填写后只使用清单原词项，留空需自行核对供应" @change="generationConfig.available_ingredients=tokens($event)"></textarea></label><label for="ai-kitchen">厨房制作条件<input id="ai-kitchen" v-model="generationConfig.kitchen_notes" class="input" maxlength="1000" placeholder="选填，例如：以蒸、炖为主，避免复杂现炒"></label><label for="ai-budget">预算与采购参考<input id="ai-budget" v-model="generationConfig.budget_notes" class="input" maxlength="300" placeholder="选填；没有价格库，不代表已完成预算核算"></label><label for="ai-capacity">每套可供应份数<input id="ai-capacity" v-model.number="generationConfig.capacity_per_option" class="input" type="number" min="1" max="10000" placeholder="留空按在院人数给出待核对上限"></label><label class="meal-checkbox"><input v-model="generationConfig.avoid_previous" type="checkbox">参考上周菜单，尽量轮换菜品</label><label class="meal-checkbox"><input v-model="generationConfig.acknowledge_pending" type="checkbox">若有未核实资料，仅生成参考计划，不据此确认老人选餐</label></fieldset>
 <div class="meal-ai-actions"><button class="btn primary" :disabled="busy||menu.status!=='draft'" @click="generateMenu"><AppIcon name="sparkles" :size="18"/>{{ generating?'正在生成七天三餐…':'智能生成本周菜单' }}</button><p v-if="generating" class="meal-hint" role="status">正在按天编排并检查，可能需要几分钟。完成前不会更改当前菜单，请保持页面打开。</p><p v-else-if="menu.status==='published'" class="meal-hint">本周已发布，请读取新一周后生成新菜单。</p></div>
 <div v-if="generationInfo" class="meal-ai-result" role="status"><b>生成完成 · 未自动保存或发布</b><p>本次在院 {{ generationInfo.summary.in_care }} 人，已核实 {{ generationInfo.summary.reviewed_count }} 人，待核实 {{ generationInfo.summary.pending_count }} 人。</p><ul><li v-for="warning in generationInfo.warnings" :key="warning">{{ warning }}</li></ul><details v-if="generationInfo.recipe_reference?.status==='success'" class="meal-check-details"><summary>查看本次外部候选食谱（{{ generationInfo.recipe_reference.count }} 份）</summary><p class="meal-hint">以下是编排参考池，不代表菜单中的每道菜均采用了这些食谱；本次参考在刷新后不保留展示。</p><article v-for="recipe in generationInfo.recipe_reference.recipes" :key="recipe.id" class="meal-source"><b>{{ recipe.name }}</b><p>食材：{{ recipe.ingredients.join('、') }}</p><ol><li v-for="(step,index) in recipe.steps" :key="index">{{ step }}</li></ol><a v-if="recipe.source_url" :href="recipe.source_url" target="_blank" rel="noopener noreferrer">查看来源原文</a></article></details><p class="meal-hint">这里是生成时的检查结果；修改并保存后，请再次执行全院覆盖检查。系统不判断临床营养达标。</p></div>
 </div></div></details>
 <div class="meal-actions"><span class="meal-workflow">生成计划 <span>→</span> 管理员修改 <span>→</span> 覆盖检查 <span>→</span> 审核发布</span><button class="btn" :disabled="busy||menu.status!=='draft'" @click="copyPrevious">复制上一周后调整</button><button class="btn primary" :disabled="busy||menu.status!=='draft'" @click="save">保存修改</button><button class="btn" :disabled="busy||!menu.id||dirty" @click="check">检查全院覆盖</button><button class="btn primary" :disabled="busy||!menu.id||dirty||menu.status!=='draft'||!report||report.missing.length>0||(report.pending.length>0&&!ack)" @click="publish">发布本周菜单</button></div>
 <p class="meal-hint">每餐提供完整餐食方案，老人选一套；生成计划需人工核对，不自动推断糖尿病、肾病等治疗饮食。标签须与饮食要求使用相同词项。已发布菜单冻结，下一周可复制再调整。</p>
 <section v-if="report" class="card meal-section"><h2>全院覆盖检查</h2><p>在院 {{ report.in_care }} 人 · 已核实 {{ report.reviewed_count }} 人 · 待核实 {{ report.pending.length }} 人 · 缺少可选方案 {{ report.missing.length }} 处</p><details v-if="report.pending.length||report.missing.length" class="meal-check-details"><summary>查看待核实人员与缺项</summary><p v-if="report.pending.length">待核实：{{ report.pending.map(r=>r.name).join('、') }}</p><ul><li v-for="r in report.missing" :key="r.resident_id+r.day+r.meal">{{ r.name }} · {{ shiftDay(menu.week_start,r.day) }} {{ mealNames[r.meal] }} 没有匹配方案</li></ul></details><label v-if="report.pending.length" class="meal-checkbox"><input v-model="ack" type="checkbox">我知晓待核实老人暂不能自助确认选餐，需工作人员跟进。</label></section>
 <div class="meal-calendar-heading"><div><h2>本周餐食安排</h2><p class="meal-hint">选择日期，查看和编辑当天三餐</p></div><span class="badge blue">{{ menu.status==='draft'?'可编辑 · 待发布':'已发布 · 只读' }}</span></div><div class="meal-days"><button v-for="n in 7" :key="n" class="btn" :class="{primary:day===n-1}" :aria-pressed="day===n-1" @click="day=n-1">周{{ '一二三四五六日'[n-1] }}<small>{{ shiftDay(menu.week_start,n-1).slice(5) }}</small><span class="meal-day-progress"><i v-for="m in 3" :key="m" :class="{filled:dayCount(n-1)>=m}"></i></span><small>{{ dayCount(n-1) }}/3 餐已安排</small></button></div>
 <div class="meal-day-title"><h2>周{{ '一二三四五六日'[day] }} · {{ shiftDay(menu.week_start,day).slice(5) }}</h2><span>每餐选择一套完整方案</span></div><section v-for="slot in slots" :key="slot.meal" class="card meal-section"><div class="meal-section-head"><h2><span class="meal-course-icon"><AppIcon :name="slot.meal==='breakfast'?'leaf':slot.meal==='lunch'?'heart':'clock'" :size="20"/></span>{{ mealNames[slot.meal] }}<small>{{ slot.options.length }} 套可选方案</small></h2><label>选餐截止（北京时间）<input v-model="slot.cutoff" class="input" type="time" :disabled="busy||menu.status!=='draft'"></label><button class="btn" :disabled="busy||menu.status!=='draft'||slot.options.length>=8" @click="slot.options.push(emptyOption())">添加可选方案</button></div>
 <p v-if="!slot.options.length" class="meal-hint">本餐尚未安排。每餐至少设置一套完整方案。</p><div class="meal-editor-grid"><article v-for="(option,index) in slot.options" :key="option.id" class="meal-option-editor"><div class="meal-option-preview"><span class="meal-option-number">{{ String(index+1).padStart(2,'0') }}</span><div><h3>{{ option.name || '待编排餐食' }}</h3><p>{{ option.foods.join(' · ') || '请填写完整餐食中的具体菜品' }}</p></div></div><div class="meal-tags"><span>{{ textures[option.texture] }}</span><span>{{ option.capacity }} 份供应</span><span v-for="tag in option.tags" :key="tag">{{ tag }}</span></div><details :open="!option.name" class="meal-edit-details"><summary>{{ menu.status==='draft'?'编辑餐食详情':'查看餐食详情' }}</summary><div class="meal-section-head"><b>方案 {{ index+1 }}</b><button class="btn" :disabled="busy||menu.status!=='draft'" @click="slot.options.splice(index,1)">移除方案</button></div><fieldset :disabled="busy||menu.status!=='draft'" class="meal-fieldset meal-grid"><label>方案名称<input v-model="option.name" class="input" maxlength="80"></label><label>具体菜品（逗号分隔）<input :value="option.foods.join('，')" class="input" @change="option.foods=tokens($event)"></label><label>全部食材（含调味/配料）<input :value="option.ingredients.join('，')" class="input" @change="option.ingredients=tokens($event)"></label><label>过敏原（核对后填写）<input :value="option.allergens.join('，')" class="input" @change="option.allergens=tokens($event)"></label><label>饮食要求标签<input :value="option.tags.join('，')" class="input" placeholder="仅填写已经核实满足的要求" @change="option.tags=tokens($event)"></label><label>食物质地<AppSelect v-model="option.texture" class="select" :disabled="busy||menu.status!=='draft'"><option v-for="(label,key) in textures" :key="key" :value="key">{{ label }}</option></AppSelect></label><label>可供应份数<input v-model.number="option.capacity" class="input" type="number" min="1" max="10000"></label><label>说明<input v-model="option.notes" class="input" maxlength="500"></label></fieldset></details></article></div></section>
 </template>
 <template v-if="tab==='needs'"><div class="card meal-section"><h2>全院饮食需求</h2><p class="meal-hint">下面展示原档案供核对。不能仅从疾病名称推断饮食禁忌；资料未知时不要确认。档案内容改变后，饮食要求需要重新核对。</p><label for="needs-filter">查找老人<input id="needs-filter" v-model="filter" class="input" placeholder="姓名、编号或位置"></label><label for="needs-person">选择核对对象<AppSelect id="needs-person" v-model="selected" class="select" :disabled="busy" @change="selectResident"><option value="">请选择老人</option><option v-for="r in requirementRows" :key="r.id" :value="r.id">{{ r.name }} · {{ r.record_no }} · {{ r.reviewed?'已核实':'待核实' }}</option></AppSelect></label><div class="meal-needs-overview"><span>在院 {{ requirements.length }} 人</span><span>待核实 {{ requirements.filter(r=>!r.reviewed).length }} 人</span></div></div>
 <form v-if="active" class="card meal-section" @submit.prevent="saveProfile"><div class="meal-section-head"><h2>{{ active.name }} · 饮食核对</h2><button type="button" class="btn primary" :disabled="busy" @click="readProfile"><AppIcon name="sparkles" :size="18"/>{{ readingBusy?'正在读取档案…':'AI 读取档案并预填' }}</button></div><p class="meal-hint">选中老人后可让 AI 提取明确记录。结果不会自动保存或核实，请对照原文确认。</p><section v-if="reading" class="meal-source" aria-label="AI读取依据"><b>AI 读取结果 · 待人工核对</b><p v-if="!reading.evidence.length">暂无有明确原文依据的可预填项目，请人工补充。</p><ul><li v-for="(item,index) in reading.evidence" :key="index">{{ ({allergens:'过敏原',avoid_ingredients:'禁用食材',required_tags:'饮食标签',allowed_textures:'食物质地'} as Record<string,string>)[item.field] }}：{{ item.value }}<small>原文：{{ item.quote }}</small></li></ul><p v-if="reading.rejected_count">有 {{ reading.rejected_count }} 条缺少有效依据的建议未采纳。</p><b v-if="reading.questions.length">待核实问题</b><ul><li v-for="question in reading.questions" :key="question">{{ question }}</li></ul></section><div class="meal-source"><p>原过敏记录：{{ active.allergies || '未记录' }}</p><p>原健康情况：{{ active.chronic_conditions || '未记录' }}</p><p>原饮食记录：{{ active.dietary_notes || '未记录' }}</p></div><fieldset :disabled="busy" class="meal-fieldset meal-grid"><label>过敏信息状态<AppSelect v-model="profile.allergy_status" class="select" :disabled="busy"><option value="unknown">尚未核实</option><option value="known">已知过敏，列出过敏原</option><option value="confirmed_none">已核对未发现已知过敏</option></AppSelect></label><label>过敏原（逗号分隔）<input :value="profile.allergens.join('，')" class="input" @change="profile.allergens=tokens($event)"></label><label>禁止使用食材<input :value="profile.avoid_ingredients.join('，')" class="input" @change="profile.avoid_ingredients=tokens($event)"></label><label>已确认必须满足的标签<input :value="profile.required_tags.join('，')" class="input" @change="profile.required_tags=tokens($event)"></label><div><b>允许的食物质地（明确选择）</b><label v-for="(label,key) in textures" :key="key" class="meal-checkbox"><input v-model="profile.allowed_textures" type="checkbox" :value="key">{{ label }}</label></div><label>核对依据 / 来源<input v-model="profile.source" class="input" required maxlength="300" placeholder="如：经核实的入住资料、医护确认记录"></label><label>备注<textarea v-model="profile.notes" class="input" rows="3" maxlength="1000"></textarea></label><label class="meal-checkbox"><input v-model="profile.confirmed" type="checkbox">上述饮食条件已经人工核实，可用于选餐规则</label></fieldset><button class="btn primary" :disabled="busy">保存饮食要求</button></form></template>
 <template v-if="tab==='kitchen'"><div class="card meal-section"><h2>备餐汇总</h2><div class="meal-toolbar"><label>日期<AppSelect v-model.number="kitchenDay" class="select" :disabled="busy"><option v-for="n in 7" :key="n" :value="n-1">{{ shiftDay(menu.week_start,n-1) }}</option></AppSelect></label><label>餐次<AppSelect v-model="kitchenMeal" class="select" :disabled="busy"><option v-for="(label,key) in mealNames" :key="key" :value="key">{{ label }}</option></AppSelect></label><button class="btn primary" :disabled="busy||!menu.id" @click="loadKitchen">刷新汇总</button></div><p class="meal-hint">统计已确认且饮食资料仍有效的选餐。需要复核者单列，不自动算入可执行备餐数；选餐不代表已进食。</p><template v-if="kitchen"><div class="meal-summary-grid"><article v-for="option in kitchen.options" :key="option.id" class="meal-summary"><b>{{ option.name }}</b><p>{{ option.foods.join('、') }}</p><strong>{{ option.count }} 份</strong><small>供应上限 {{ option.capacity }} 份</small></article></div><h3>需人工复核（{{ kitchen.needs_review.length }}）</h3><p>{{ kitchen.needs_review.map(r=>`${r.name}（${r.location||'位置未记'}）`).join('、') || '暂无' }}</p><h3>未选餐（{{ kitchen.unselected.length }}）</h3><p>{{ kitchen.unselected.map(r=>`${r.name}（${r.location||'位置未记'}）`).join('、') || '暂无' }}</p></template></div></template>
</div></template>
<style src="../../styles/meals.css"></style>
